const b = $input.first().json.body || {};
const clean = s => String(s ?? '').replace(/<[^>]*>/g, '').trim();
if (b.website) { throw new Error('Rejected: honeypot field filled (spam)'); }
const lead = {
  name: clean(b.name).slice(0, 80),
  email: clean(b.email).slice(0, 120),
  phone: clean(b.phone).slice(0, 30),
  message: clean(b.message).slice(0, 1500),
  clinic: clean(b.clinic || 'Clinique Physio Rideau (DEMO)').slice(0, 80),
  mock: b.mock === true,
  receivedAt: new Date().toISOString(),
};
const errors = [];
if (!lead.name) errors.push('name');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(lead.email)) errors.push('email');
if (lead.message.length < 5) errors.push('message');
if (errors.length) { throw new Error('Invalid input: ' + errors.join(', ')); }
return [{ json: lead }];

// DEMO ONLY: canned reply used when the request has "mock": true (tests without an API key).
const lead = $input.first().json;
const fr = /\b(bonjour|bonsoir|je |vous|rendez-vous|svp|merci|nous|j'aimerais|disponibilit)/i.test(lead.message);
const urgent = /(chest pain|can't breathe|cannot breathe|douleur (à|a) la poitrine|difficult(é|e) (à|a) respirer)/i.test(lead.message);
const health = /(pain|douleur|injur|blessure|back|dos|knee|genou|surgery|chirurgie)/i.test(lead.message);
const first = lead.name.split(' ')[0];
const out = fr ? {
  language: 'fr', intent: 'new_booking', urgent, contains_health_info: health,
  subject: 'Votre demande de rendez-vous',
  body: `Bonjour ${first},\n\nMerci de nous avoir contactés. Nous serions heureux de vous accueillir à la clinique. Vous pouvez choisir l\u2019heure qui vous convient ici : https://example.com/book-demo\n\nSi vous préférez, répondez simplement à ce courriel avec vos disponibilités.\n\nL\u2019équipe de ${lead.clinic}`
} : {
  language: 'en', intent: 'new_booking', urgent, contains_health_info: health,
  subject: 'Your appointment request',
  body: `Hi ${first},\n\nThanks for reaching out. We\u2019d be happy to see you at the clinic. You can pick a time that suits you here: https://example.com/book-demo\n\nIf you prefer, just reply to this email with your availability.\n\nThe ${lead.clinic} team`
};
return [{ json: { ...lead, source: 'mock', claudeText: JSON.stringify(out) } }];

const lead = $input.first().json;
const BOOKING_URL = 'https://example.com/book-demo';  // placeholder for the demo
const system = "You are the front-desk assistant for {clinic}, a private physiotherapy clinic in the Ottawa-Gatineau area. Write a short, warm reply to a new-patient inquiry.\\nRULES:\\n1. Detect the language of the message (en or fr) and reply in that language. If it is mixed, reply in French.\\n2. Never give medical advice, diagnoses or treatment suggestions. Never ask the person for health details.\\n3. If the message contains health information (symptoms, injuries, conditions, medications), set contains_health_info=true and do NOT repeat that information in your reply.\\n4. If the message suggests an emergency (e.g. chest pain, trouble breathing, severe bleeding), set urgent=true and tell the person to call 911 or go to the nearest emergency department instead of waiting for a booking.\\n5. Offer to book through this link: {booking}. Length 60-110 words. Sign as 'L\\u2019\\u00e9quipe de {clinic}' (French) or 'The {clinic} team' (English).\\n6. intent must be one of: new_booking, pricing, insurance, hours_location, other.\\nReturn ONLY a JSON object, no other text, with keys: language, intent, urgent, contains_health_info, subject, body.".replaceAll('{clinic}', lead.clinic).replaceAll('{booking}', BOOKING_URL);
const claudeBody = {
  model: 'claude-haiku-5-5',
  max_tokens: 600,
  system,
  messages: [{ role: 'user', content: JSON.stringify({ name: lead.name, message: lead.message }) }],
};
return [{ json: { ...lead, claudeBody } }];

const lead = $input.first().json;
let raw = lead.claudeText;
if (raw === undefined) {            // real Claude response
  raw = (lead.content && lead.content[0] && lead.content[0].text) || '';
}
let d, parseOk = true;
try {
  d = JSON.parse(String(raw).replace(/^```json\s*|^```\s*|```\s*$/gm, '').trim());
} catch (e) { parseOk = false; d = {}; }
const required = ['language', 'intent', 'subject', 'body'];
const complete = parseOk && required.every(k => typeof d[k] === 'string' && d[k].length > 0);
const needsHuman = !complete || d.urgent === true || d.contains_health_info === true;
const original = $('Validate input').first().json;
return [{ json: {
  status: needsHuman ? 'needs_human_review' : 'draft_pending_approval',
  reason: !complete ? 'model output invalid' : d.urgent ? 'urgent wording detected' : d.contains_health_info ? 'health info in message' : null,
  language: d.language || null,
  intent: d.intent || null,
  draft: complete ? { to: original.email, subject: d.subject, body: d.body } : null,
  source: lead.source || 'claude',
  respondedInMs: Date.now() - new Date(original.receivedAt).getTime(),
  lead: { name: original.name, clinic: original.clinic },
} }];
